window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[261]={"id":"261","numero":261,"titre":"Néphropathies glomérulaires","objectifs":[{"id":"261-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une néphropathie glomérulaire","contenu":"<p>Le diagnostic d'une néphropathie glomérulaire repose sur une démarche en trois temps : <strong>identifier le syndrome glomérulaire</strong>, rechercher systématiquement une <strong>entité pathologique sous-jacente</strong>, puis souvent <strong>confirmer par l'<span class=\"kw-bio\">histologie</span> rénale</strong> (microscopie optique + <span class=\"kw-bio\">immunofluorescence</span>).</p>\n      <div class=\"obj-callout success\"><strong>À comprendre.</strong> <span class=\"kw-clinique\">Les</span> glomérulopathies ont une présentation et une <span class=\"kw-clinique\">évolution</span> <span class=\"kw-clinique\">aiguë et/ou chronique</span>, sont parfois <span class=\"kw-clinique\">secondaires</span> à une maladie générale (infection, métabolique, <span class=\"kw-etio\">auto-immune</span>), et l'atteinte rénale peut être <span class=\"kw-clinique\">isolée</span>. <span class=\"kw-def\">Pronostic</span>, traitement et <span class=\"kw-def\">surveillance</span> sont <strong>spécifiques à chacune</strong>.</div>\n      <p><strong>Le syndrome glomérulaire</strong> — la pathologie glomérulaire est évoquée devant 1 ou 2 des signes suivants :</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Protéinurie glomérulaire</strong></span></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-bio\">BU</span> (<span class=\"kw-def\">dépistage</span>) :</strong> 2+ (≈ <span class=\"kw-chiffre\">1 g/L</span>) · 3+ (≈ <span class=\"kw-chiffre\">3 g/L</span>) · 4+ (&gt;<span class=\"kw-chiffre\"> 20 g/L</span>)</li>\n                <li><strong>Dosage pondéral (confirmation) :</strong> <span class=\"kw-bio\">albuminurie</span> <span class=\"kw-chiffre\">&gt; 300 mg/j</span> (ou <span class=\"kw-chiffre\">30 mg</span>/mmol de créatininurie), souvent débit glomérulaire <span class=\"kw-chiffre\">&gt; 1 g/j</span></li>\n                <li><strong>EPU :</strong> composée principalement d'<span class=\"kw-bio\">albumine (≥ 60 %)</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Hématurie</strong></span></td>\n            <td>\n              <ul>\n                <li><strong>Macroscopique :</strong> <span class=\"kw-clinique\">totale</span>, <span class=\"kw-clinique\">indolore</span>, <span class=\"kw-clinique\">sans caillots</span></li>\n                <li><strong>Microscopique :</strong> GR <span class=\"kw-chiffre\">&gt; 10/mm³</span> ou <span class=\"kw-chiffre\">10⁴/mL</span>, ± <span class=\"kw-clinique\">GR déformés</span> ou <span class=\"kw-clinique\">cylindres hématiques</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Signes associés</strong></span> (inconstants)</td>\n            <td><span class=\"kw-etio\">HTA</span> · <span class=\"kw-clinique\">œdèmes</span> · <span class=\"kw-ci\">insuffisance rénale</span> (aiguë ou chronique)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La <span class=\"kw-clinique\">cylindrurie hématique</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">hématies déformées</span> affirment l'origine <strong>glomérulaire</strong> de l'<span class=\"kw-bio\">hématurie</span>. La combinatoire de ces signes définit les différents <strong>syndromes glomérulaires</strong>, dont l'identification oriente l'enquête étiologique et l'<span class=\"kw-bio\">histologie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-bio\">Protéinurie</span>, <span class=\"kw-clinique\">syndrome néphrotique</span> · 260 — <span class=\"kw-bio\">Hématurie</span> · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":1},{"id":"261-2","rang":"A","rubrique":"Définition","titre":"Connaître les différents types de syndromes glomérulaires","contenu":"<p>La combinaison des signes du syndrome glomérulaire (<span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span>, IR) définit <strong>cinq grands syndromes glomérulaires</strong>, chacun orientant vers un groupe d'étiologies.</p>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Tableau · étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Hématurie macroscopique récidivante</strong></span></td>\n            <td><span class=\"kw-bio\">hématurie</span> macroscopique récidivante (totale, indolore, sans caillots), ± <span class=\"kw-bio\">hématurie</span> microscopique entre <span class=\"kw-clinique\">les</span> épisodes, <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-etio\">HTA</span><br><strong>Étiologies :</strong> <span class=\"kw-etio\">syndrome d'Alport</span> · <span class=\"kw-etio\">néphropathie à IgA primitive (Berger)</span> — ici l'<span class=\"kw-bio\">hématurie</span> macroscopique peut être <span class=\"kw-clinique\">contemporaine d'une infection ORL</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Glomérulonéphrite chronique</strong></span></td>\n            <td><span class=\"kw-bio\">protéinurie</span> glomérulaire, ± <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-ci\">insuffisance rénale</span><br><strong>Étiologie :</strong> <span class=\"kw-etio\">toutes les glomérulopathies chroniques</span> peuvent en être à l'origine (intérêt d'une PEC précoce pour prévenir la progression de l'IRC)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Syndrome néphrotique</strong></span></td>\n            <td><span class=\"kw-bio\">protéinurie</span> abondante + hypoalbuminémie ; <span class=\"kw-clinique\">pur</span> ou <span class=\"kw-clinique\">impur</span> (<span class=\"kw-bio\">hématurie</span> micro, <span class=\"kw-etio\">HTA</span>, IR organique)<br><strong>Étiologies :</strong> SN secondaire (<span class=\"kw-clinique\">lupus</span>, amylose, <span class=\"kw-etio\">diabète</span>, cryoglobulinémie, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span>, VIH) · SN idiopathique (<span class=\"kw-etio\">SNLGM</span>, <span class=\"kw-etio\">HSF primitive</span>) · <span class=\"kw-etio\">GEM</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Syndrome néphritique aigu</strong></span></td>\n            <td>début brutal (quelques jours) : <span class=\"kw-clinique\">œdèmes</span>, anasarque, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-bio\">hématurie</span> (macro ou micro), <span class=\"kw-bio\">protéinurie</span> glomérulaire, IRA modérée, oligurie<br><strong>Étiologie type :</strong> <span class=\"kw-etio\">GNA post-infectieuse</span> (&gt; 12 j après une infection <span class=\"kw-etio\">bactérienne</span>, <span class=\"kw-bio\">hypocomplémentémie</span> +++)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>GNRP (rapidement progressive)</strong></span></td>\n            <td><span class=\"kw-ci\">insuffisance rénale</span> rapidement progressive (jours-semaines), <span class=\"kw-bio\">hématurie</span> (parfois macroscopique), <span class=\"kw-bio\">protéinurie</span> glomérulaire<br><strong>Type 1</strong> dépôts linéaires anti-MBG : <span class=\"kw-etio\">Goodpasture</span> · <strong>Type 2</strong> dépôts granuleux de complexes immuns : Berger, <span class=\"kw-clinique\">purpura</span> rhumatoïde, LED, cryoglobulinémie, GNAPI · <strong>Type 3</strong> sans dépôts : <span class=\"kw-etio\">GPA</span> (cANCA <span class=\"kw-bio\">anti-PR3</span>), <span class=\"kw-etio\">MPA</span> (pANCA <span class=\"kw-bio\">anti-MPO</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Deux syndromes sont des <span class=\"kw-alerte\">urgences</span> : le <span class=\"kw-alerte\">syndrome néphritique aigu</span> et surtout la <span class=\"kw-alerte\">GNRP</span>. Le <span class=\"kw-clinique\">syndrome néphrotique</span> se définit biologiquement (cf. item 259), <span class=\"kw-clinique\">les</span> autres se reconnaissent sur la cinétique et l'association des signes.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-clinique\">Syndrome néphrotique</span> · 260 — <span class=\"kw-bio\">Hématurie</span> · 193 — Vascularites · 194 — <span class=\"kw-clinique\">Lupus</span></em></p>","frequence":1},{"id":"261-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence et l’épidémiologie des principales maladies glomérulaires","contenu":"<p>Quelques repères épidémiologiques structurants, à connaître par entité.</p>\n      <table >\n        <thead><tr><th>Entité</th><th><span class=\"kw-def\">Épidémiologie</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Néphropathie à IgA</strong></span> (Berger)</td>\n            <td><span class=\"kw-alerte\">glomérulopathie primitive la plus fréquente dans le monde</span> ; <span class=\"kw-def\">prévalence</span> des formes symptomatiques ≈ <span class=\"kw-chiffre\">1,5/1000</span> ; <span class=\"kw-alerte\">5ᵉ cause de dialyse</span> en France ; adulte jeune, prédominance masculine</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>SN à LGM</strong></span> (SNLGM)</td>\n            <td><span class=\"kw-alerte\">90 % des syndromes néphrotiques de l'enfant</span> ;<span class=\"kw-chiffre\"> 10 %</span> des SN idiopathiques de l'adulte ; enfant <span class=\"kw-chiffre\">1-10 ans</span> (surtout &lt;<span class=\"kw-chiffre\"> 6 ans</span>), prédominance masculine</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>HSF</strong></span> (plus rare)</td>\n            <td><span class=\"kw-chiffre\">15-20 %</span> des SN de l'adulte jeune ;<span class=\"kw-chiffre\"> 10-15 %</span> des SN de l'enfant ; prédominance masculine</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>GEM</strong></span></td>\n            <td><span class=\"kw-alerte\">2ᵉ cause de syndrome néphrotique de l'adulte (≈ 40 %)</span>, après la néphropathie diabétique ; rare chez l'enfant (&lt;<span class=\"kw-chiffre\"> 5 %</span>), plus fréquente <span class=\"kw-chiffre\">&gt; 60 ans</span> ; prédominance masculine</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>GNA post-infectieuse</strong></span></td>\n            <td><span class=\"kw-clinique\">incidence en diminution</span> ; forme typique post-streptococcique de l'enfant ; <span class=\"kw-def\">pronostic</span> excellent</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-clinique\">Les</span> 3 repères « causes de SN ».</strong> 1ʳᵉ cause chez l'<span class=\"kw-clinique\">adulte</span> = <span class=\"kw-etio\">diabète</span> ; 2ᵉ cause de l'adulte = <span class=\"kw-etio\">GEM</span> ; 1ʳᵉ cause chez l'<span class=\"kw-clinique\">enfant</span> = <span class=\"kw-etio\">SNLGM</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-clinique\">Syndrome néphrotique</span> · 247 — <span class=\"kw-etio\">Diabète</span> · 264 — IRC / dialyse</em></p>","frequence":0},{"id":"261-4","rang":"A","rubrique":"Étiologie","titre":"Connaître les principales étiologies des maladies glomérulaires","contenu":"<p><span class=\"kw-clinique\">Les</span> étiologies se regroupent par grands cadres. Devant un syndrome glomérulaire, l'enquête recherche systématiquement une <strong>maladie générale sous-jacente</strong>.</p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Étiologies · glomérulopathies associées</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Infections bactériennes</strong></span></td>\n            <td><strong>Aiguës</strong> (angine, infection cutanée, <span class=\"kw-clinique\">endocardite</span>, arthrite) : GNA post-infectieuse, néphropathie à <span class=\"kw-chiffre\">IgA</span><br><strong>Chroniques</strong> (endocardite d'Osler, ostéomyélite, <span class=\"kw-etio\">tuberculose</span>) : GN membrano-proliférative, amylose AA</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Infections virales</strong></span></td>\n            <td><span class=\"kw-etio\">VIH</span> : HIVAN · <span class=\"kw-etio\">Hépatite B</span> : GEM · <span class=\"kw-etio\">Hépatite C</span> : GEM, rein de cryoglobulinémie (GNRP type 2, GNMP)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Vascularites</strong></span></td>\n            <td>néphropathie à <span class=\"kw-chiffre\">IgA</span> (<span class=\"kw-clinique\">purpura</span> rhumatoïde) · rein de cryoglobulinémie · GNRP : type <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> G</span>oodpasture (anti-MBG), type 2 <span class=\"kw-clinique\">purpura</span> rhumatoïde, type <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> G</span>PA (cANCA <span class=\"kw-bio\">anti-PR3</span>) / MPA (pANCA anti-MPO)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Inflammatoire</strong></span></td>\n            <td>maladies inflammatoires chroniques (<span class=\"kw-clinique\">PR</span>, SpA, <span class=\"kw-clinique\">MICI</span>, maladie périodique) → <span class=\"kw-etio\">amylose AA</span>, néphropathie à <span class=\"kw-chiffre\">IgA</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Génétique</strong></span></td>\n            <td><span class=\"kw-etio\">syndrome d'Alport</span> (anomalie <span class=\"kw-etio\">congénitale</span> de la MBG)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Autres</strong></span></td>\n            <td>néphropathie diabétique · <span class=\"kw-clinique\">lupus</span> · myélome · amylose AL · Randall</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Tests biologiques prescrits selon <span class=\"kw-clinique\">les</span> conclusions cliniques</strong> (orientation étiologique) :</p>\n      <table >\n        <thead><tr><th>Test</th><th>Oriente vers</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">AAN, anti-ADN natifs</span></td><td><span class=\"kw-clinique\">lupus</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Complément CH50, C3, C4</span></td><td>GN post-infectieuse, <span class=\"kw-clinique\">lupus</span>, cryoglobulinémie</td></tr>\n          <tr><td><span class=\"kw-bio\">ANCA</span></td><td>vascularites</td></tr>\n          <tr><td><span class=\"kw-bio\">Anticorps anti-MBG</span></td><td>maladie de Goodpasture</td></tr>\n          <tr><td><span class=\"kw-bio\">Cryoglobulinémie + sérologie VHC</span></td><td>rein de cryoglobulinémie</td></tr>\n          <tr><td><span class=\"kw-bio\">Immuno-EP protéines plasma/urine + chaînes légères</span></td><td>amylose AL, maladie de dépôts d'Ig (Randall)</td></tr>\n          <tr><td><span class=\"kw-bio\">Anticorps anti-PLA2R</span></td><td>GEM primitive</td></tr>\n          <tr><td><span class=\"kw-bio\">Sérologies virales</span></td><td><span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span>, VIH</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-clinique\">Lupus</span> · 193 — Vascularites · 167 — Hépatites · 169 — <span class=\"kw-etio\">VIH</span> · 320 — Myélome / amylose</em></p>","frequence":1},{"id":"261-5","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir les principales indications de la ponction biopsie rénale (PBR), les contre-indications, les modalités et les complications de la PBR","contenu":"<p>Objectif <span class=\"kw-alerte\">à très fort rendement EDN</span> ⭐⭐⭐⭐⭐⭐⭐. L'indication de PBR doit être <strong>posée ou confirmée par un néphrologue</strong> devant un syndrome glomérulaire.</p>\n      <p><strong>1 · Indications · intérêts</strong></p>\n      <table >\n        <thead><tr><th>Visée</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Diagnostique</strong></td><td>le type histologique oriente l'enquête étiologique</td></tr>\n          <tr><td><strong>Thérapeutique</strong></td><td>certaines néphropathies relèvent d'un traitement étiopathogénique</td></tr>\n          <tr><td><strong>Pronostique</strong></td><td>importance de la fibrose, sévérité des lésions vasculaires…</td></tr>\n        </tbody>\n      </table>\n      <p><strong>2 · <span class=\"kw-clinique\">Les</span> 5 situations où la PBR n'est PAS indiquée</strong> devant un syndrome glomérulaire :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Conditions</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ci\"><strong>Dangerosité de la biopsie</strong></span></td><td>rein unique, trouble de l'hémostase…</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>SN à LGM</strong></span> (néphrose lipoïdique)</td><td><span class=\"kw-clinique\">enfant 1-10 ans</span> (jusqu'à<span class=\"kw-chiffre\"> 11 ans</span> selon pédiatrie) + <span class=\"kw-clinique\">SN pur</span> + <span class=\"kw-clinique\">pas de signes extra-rénaux</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Glomérulopathie diabétique</strong></span></td><td><strong>Non indiquée si :</strong> <span class=\"kw-etio\">diabète</span> ancien + <span class=\"kw-clinique\">rétinopathie</span> + SN sans <span class=\"kw-bio\">hématurie</span><br><strong>Indiquée si :</strong> <span class=\"kw-etio\">diabète</span> récent (&lt;<span class=\"kw-chiffre\"> 5-10 ans</span>), sans RD, signes extra-rénaux ; ou syndrome <span class=\"kw-alerte\">rapidement progressif</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Glomérulopathie héréditaire</strong></span> (ex. Alport)</td><td>déjà identifiée dans la famille, si aucun traitement spécifique n'est à proposer</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Suspicion d'amylose (adulte)</strong></span></td><td>si la <span class=\"kw-clinique\">biopsie des glandes salivaires accessoires</span> établit le diagnostic (maladie systémique, dépôts semblables)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>3 · <span class=\"kw-ci\">Contre-indications</span></strong> ⚠️</p>\n      <ul>\n        <li><span class=\"kw-ci\">Rein unique</span> (anatomique ou fonctionnel), kystes multiples, rein en fer à cheval</li>\n        <li><span class=\"kw-ci\">HTA mal contrôlée</span> (CI jusqu'au contrôle de l'<span class=\"kw-etio\">HTA</span>)</li>\n        <li><span class=\"kw-ci\">Périartérite noueuse</span> (confirmée ou suspectée)</li>\n        <li><span class=\"kw-ci\">Pyélonéphrite aiguë</span> (CI temporaire) — mais un <span class=\"kw-bio\">ECBU</span> positif n'est pas une CI</li>\n        <li><span class=\"kw-alerte\">Anémie &lt; 8 g/dL = CI absolue</span> (seuil recommandé &gt;<span class=\"kw-chiffre\"> 10 g/dL</span>)</li>\n        <li><strong>Troubles de l'hémostase :</strong> arrêt des <span class=\"kw-ttt\">antiagrégants</span> — <span class=\"kw-ttt\">aspirine / clopidogrel / ticagrelor (5 j)</span>, <span class=\"kw-ttt\">prasugrel (7 j)</span> ; <span class=\"kw-alerte\">thrombopénie &lt; 50 G/L = CI absolue</span> (seuil recommandé &gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> G/L</span>) ; si trouble d'hémostase : envisager une <span class=\"kw-ttt\">PBR par voie transjugulaire</span></li>\n      </ul>\n      <p><strong>4 · Préalable &amp; modalités</strong></p>\n      <table >\n        <thead><tr><th>Étape</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Préalable</strong></span> 🏥</td><td><span class=\"kw-clinique\">hospitalisation indispensable</span> : bilan d'hémostase (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>), groupe sanguin, RAI ; imagerie récente recommandée (rechercher une CI)</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Modalités</strong></span></td><td><span class=\"kw-ttt\">biopsie</span> <span class=\"kw-clinique\">percutanée</span>, sous <span class=\"kw-clinique\">contrôle échographique</span>, après <span class=\"kw-clinique\">anesthésie locale</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Prélèvements</strong></span></td><td><span class=\"kw-chiffre\">2 carottes</span> : 1 pour la microscopie optique, 1 pour l'<span class=\"kw-bio\">immunofluorescence</span> (TOUTE PBR) ; ± 1 prélèvement pour la <span class=\"kw-clinique\">microscopie électronique</span> (suspicion d'Alport, de maladie de dépôts d'Ig)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>5 · Complications</strong></p>\n      <div class=\"callout callout-danger\">\n        <p style=\"margin:0 0 6px\"><strong>⚠️ Complications aiguës (hémorragiques)</strong> — PEC parfois par <span class=\"kw-alerte\">embolisation</span>, voire <span class=\"kw-alerte\">néphrectomie d'hémostase</span></p>\n        <ul style=\"margin:0\">\n          <li><strong>Hématome intra-rénal</strong> (<span class=\"kw-chiffre\">1-10 %</span>) : <span class=\"kw-clinique\">hématurie macroscopique</span>, caillots, colique néphrétique, rétention d'urine</li>\n          <li><strong>Hématome péri-rénal</strong> : douleur</li>\n          <li><strong>Hématome rétro-péritonéal</strong> (<span class=\"kw-chiffre\">0,5-1 %</span>) : <span class=\"kw-alerte\">syndrome hémorragique</span> (risque de <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span>)</li>\n        </ul>\n      </div>\n      <table >\n        <thead><tr><th>Complications chroniques</th><th></th></tr></thead>\n        <tbody>\n          <tr><td>Souffle · <span class=\"kw-etio\">HTA</span> · risque de <span class=\"kw-alerte\">rupture</span></td><td><span class=\"kw-clinique\">Fistule artério-veineuse</span> (<span class=\"kw-chiffre\">0,1-0,5 %</span>) : diagnostic artériographique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Deux <span class=\"kw-ci\">CI absolues</span> chiffrées : <span class=\"kw-alerte\">anémie &lt; 8 g/dL</span> et <span class=\"kw-alerte\">thrombopénie &lt; 50 G/L</span>. Toujours <span class=\"kw-chiffre\">2 carottes</span> (MO + IF). Si hémostase fragile → voie <span class=\"kw-ttt\">transjugulaire</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — Indications de la PBR dans le SN · 326 — Prescription des antithrombotiques</em></p>","frequence":7},{"id":"261-6","rang":"B","rubrique":"Définition","titre":"Connaître les principales lésions glomérulaires élémentaires: prolifération, dépôts, sclérose","contenu":"<p>L'analyse histologique repose sur deux familles de lésions élémentaires : <span class=\"kw-clinique\">les</span> <strong>proliférations cellulaires</strong> et les <strong>modifications du tissu conjonctif</strong> (dont la <span class=\"kw-ttt\">sclérose</span>), complétées par l'analyse des <strong>dépôts</strong> (IF +++).</p>\n      <p><strong>1 · Proliférations cellulaires</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme · présentation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Endocapillaire</strong></span></td>\n            <td>cellules <span class=\"kw-clinique\">endothéliales</span> + <span class=\"kw-clinique\">mésangiales</span> + <span class=\"kw-ttt\">infiltration</span> par cellules inflammatoires (<span class=\"kw-clinique\">PNN</span>, macrophages) ; <span class=\"kw-alerte\">toujours liée à des dépôts endomembraneux</span> ; présentation : atteinte <span class=\"kw-etio\">inflammatoire</span> aiguë (GNA), IR modérée inconstante</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Extracapillaire</strong></span></td>\n            <td>cellules <span class=\"kw-clinique\">épithéliales pariétales</span> plus nombreuses après <span class=\"kw-clinique\">nécrose</span> glomérulaire → formation d'un <span class=\"kw-alerte\">croissant</span> dans la chambre urinaire, <span class=\"kw-clinique\">évolution</span> vers la fibrose ; présentation : <span class=\"kw-alerte\">IRA (GNRP à croissants)</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>2 · Modifications du tissu conjonctif</strong></p>\n      <ul>\n        <li><strong>Épaississement irrégulier de la MBG :</strong> en réponse à des <span class=\"kw-clinique\">dépôts extra-membraneux</span></li>\n        <li><strong>Doubles contours de la MBG :</strong> souvent liés à des <span class=\"kw-clinique\">dépôts sous-endothéliaux</span></li>\n        <li><strong>Glomérulosclérose</strong> (↑ matrice conjonctive du mésangium, collagène) : soit une partie du glomérule détruit (<span class=\"kw-clinique\">sclérose segmentaire</span>), soit la totalité (glomérule scléreux « <span class=\"kw-clinique\">en pain à cacheter</span> »)</li>\n      </ul>\n      <p><strong>3 · Répartition des lésions</strong></p>\n      <table >\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Segmentaire</strong></span> / <span class=\"kw-def\"><strong>Globale</strong></span></td><td>une partie / tout le glomérule</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Focale</strong></span> / <span class=\"kw-def\"><strong>Diffuse</strong></span></td><td>quelques glomérules / tous <span class=\"kw-clinique\">les</span> glomérules</td></tr>\n        </tbody>\n      </table>\n      <p><strong>4 · Analyse des dépôts</strong> (l'IF reste l'examen de choix)</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Localisation</strong></span></td><td><strong>Intra-membraneux</strong> (dans la MBG, rares) · <strong>Extra-membraneux</strong> (versant externe, sous-épithéliaux : entre MBG et podocytes) · <strong>Endo-membraneux</strong> (versant interne : <span class=\"kw-clinique\">mésangiaux</span> et <span class=\"kw-clinique\">sous-endothéliaux</span>)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Aspect</strong></span></td><td><strong>Granuleux</strong> (dépôts immuns, <span class=\"kw-clinique\">les</span> plus fréquents) · <strong>Linéaires</strong> (anti-MBG, dépôts d'Ig monoclonales) · <strong>Volumineux/homogènes</strong> (amyloïdes ; hyalins de l'HSF)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Nature</strong></span></td><td>chaînes d'Ig (<span class=\"kw-bio\">IgG, IgM, IgA, kappa, lambda</span>) · compléments (<span class=\"kw-bio\">C1q, C3</span>) · matrice glycosylée (<span class=\"kw-etio\">diabète</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Deux règles de lecture : la prolifération <span class=\"kw-clinique\">endocapillaire</span> est <strong>toujours liée à des dépôts endomembraneux</strong> ; la prolifération <span class=\"kw-clinique\">extracapillaire</span> (croissants) signe la <strong>GNRP</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : obj. « Caractéristiques histologiques des néphropathies <span class=\"kw-clinique\">les</span> plus fréquentes » (ce même item)</em></p>","frequence":0,"liens":[{"href":"https://www.jle.com/fr/revues/ndt/e-docs/lesions_elementaires_des_glomerules_chez_ladulte_324256/article.phtml?tab=texte","label":"JLE — Lésions élémentaires des glomérules chez l’adulte"}]},{"id":"261-7","rang":"B","rubrique":"Définition","titre":"Connaître les principales caractéristiques histologiques des néphropathies glomérulaires les plus fréquentes","contenu":"<p>Objectif <span class=\"kw-alerte\">à fort rendement EDN</span> ⭐⭐⭐⭐⭐. Tableau de synthèse <strong>microscopie optique (MO)</strong> × <strong><span class=\"kw-bio\">immunofluorescence</span> (IF)</strong> des principales entités.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Microscopie optique</th><th><span class=\"kw-bio\">Immunofluorescence</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>SNLGM</strong></span></td>\n            <td>glomérules <strong>normaux</strong> (pas de prolifération) ; ME (non obl<span class=\"kw-chiffre\">iga</span>toire) : <span class=\"kw-clinique\">fusion des pieds des podocytes</span> (effacement des pédicelles)</td>\n            <td><span class=\"kw-alerte\">Pas de dépôts</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>HSF</strong></span></td>\n            <td><strong>Segmentaire</strong> (partie du glomérule) + <strong>Focale</strong> (certains glomérules) ; <span class=\"kw-clinique\">dépôts hyalins</span> et lésions de <span class=\"kw-ttt\">sclérose</span></td>\n            <td>pas de dépôts immuns ; fixation non spécifique sur <span class=\"kw-clinique\">les</span> dépôts hyalins (<span class=\"kw-bio\">IgM, C3</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>GEM</strong></span></td>\n            <td>pas de prolifération ; lésions diffuses et globales de la MBG — <strong>St. 1</strong> normal/épaississement, <strong>St. 2</strong> <span class=\"kw-clinique\">spicules</span> sur le versant externe, <strong>St. 3</strong> épaississement irrégulier (aspect en « <span class=\"kw-clinique\">chaînette</span> »)</td>\n            <td>dépôts <strong>extra-membraneux</strong>, <strong>granuleux</strong> : <span class=\"kw-bio\">IgG, C3</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Néphropathie à IgA</strong></span></td>\n            <td>hypertrophie de la matrice mésangiale ± prolifération mésangiale ; prolifération endocapillaire ± extracapillaire segmentaire et focale ; <span class=\"kw-clinique\">lésions d'âges différents</span> (poussées)</td>\n            <td>dépôts <strong>mésangiaux</strong> de <span class=\"kw-bio\">IgA</span> et <span class=\"kw-bio\">C3</span>, ± endocapillaires</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>GNRP</strong></span></td>\n            <td>foyers de <span class=\"kw-clinique\">nécrose glomérulaire</span> (<span class=\"kw-alerte\">rupture</span> MBG, <span class=\"kw-bio\">fibrine</span>) ; prolifération <span class=\"kw-alerte\">extracapillaire = croissant</span> ; ± prolifération endocapillaire ; ± lésions fibreuses séquellaires</td>\n            <td><strong>T1</strong> linéaire <span class=\"kw-chiffre\">IgG</span> anti-MBG (Goodpasture) · <strong>T2</strong> granuleux (LED : IgG/IgA/IgM/<span class=\"kw-bio\">C3</span>/C1q ; cryo : IgG/IgM/C3 ; infections : C3 ; IgA/<span class=\"kw-clinique\">purpura</span> : <span class=\"kw-chiffre\">IgA</span>/C3) · <strong>T3</strong> pauci-immune (<span class=\"kw-clinique\">GPA</span> cANCA, MPA pANCA)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>GNAPI</strong></span></td>\n            <td>prolifération <span class=\"kw-clinique\">endocapillaire diffuse</span> (PNN ++) ; volumineux dépôts extra-membraneux (« <span class=\"kw-clinique\">humps</span> ») ; prolifération extracapillaire si forme sévère</td>\n            <td>dépôts mésangiaux et extra-membraneux, aspect en « <span class=\"kw-clinique\">ciel étoilé</span> » : <span class=\"kw-bio\">C3</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout success\">\n        <p style=\"margin:0 0 6px\"><strong>Deux règles de raisonnement.</strong></p>\n        <ul style=\"margin:0\">\n          <li>Toutes <span class=\"kw-clinique\">les</span> glomérulopathies avec <strong>prolifération</strong> sont aussi à l'origine de dépôts en IF, <strong>sauf la GNRP pauci-immune</strong> (type 3).</li>\n          <li>Toutes <span class=\"kw-clinique\">les</span> glomérulopathies sont à l'origine soit de <strong>prolifération</strong>, soit de <strong>dépôts</strong>, <strong>sauf le SNLGM</strong> (ni l'un ni l'autre).</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>Reconnaissance express en IF.</strong> <span class=\"kw-bio\">IgA mésangiales</span> → Berger · <span class=\"kw-bio\">IgG + C3 extra-membraneux granuleux</span> → GEM · <span class=\"kw-bio\">IgG linéaire</span> → Goodpasture · <span class=\"kw-bio\">C3 « ciel étoilé »</span> → GNAPI · <span class=\"kw-clinique\">pauci-immune</span> → <span class=\"kw-clinique\">vascularite</span> à <span class=\"kw-bio\">ANCA</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-clinique\">Syndrome néphrotique</span> · 193 — Vascularites · 194 — <span class=\"kw-clinique\">Lupus</span></em></p>","frequence":5},{"id":"261-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques et biologiques conduisant suspecter un syndrome néphrotique à lésions glomérulaires minimes (SNLGM)","contenu":"<p>Le SNLGM (anciennement néphrose lipoïdique) est la <strong>1ʳᵉ cause de <span class=\"kw-clinique\">syndrome néphrotique</span> de l'enfant</strong>. C'est l'archétype du <span class=\"kw-clinique\">syndrome néphrotique pur</span>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Terrain</strong></span></td><td>enfant de <span class=\"kw-chiffre\">1 à 10 ans</span> (surtout &lt;<span class=\"kw-chiffre\"> 6 ans</span>), plus fréquent chez le <span class=\"kw-clinique\">garçon</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Facteur déclenchant</strong></span></td><td>épisode <span class=\"kw-etio\">infectieux</span> ; <span class=\"kw-def\">contact</span> avec un <span class=\"kw-clinique\">allergène</span> sur <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">atopique</span></td></tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Présentation</strong></span></td>\n            <td>début souvent <span class=\"kw-clinique\">brutal</span> : <span class=\"kw-alerte\">syndrome œdémateux</span> généralisé (prise de poids, anasarque possible), douleurs abdominales fréquentes chez l'enfant (hypovolémie). <span class=\"kw-clinique\">SN pur</span> (pas d'<span class=\"kw-bio\">hématurie</span>, pas d'<span class=\"kw-etio\">HTA</span>, pas d'IR) = SNLGM ; <span class=\"kw-clinique\">SN impur</span> (<span class=\"kw-bio\">hématurie</span> micro, <span class=\"kw-etio\">HTA</span>, ± IR) évoque l'HSF. Complications parfois révélatrices : IRA, thromboses, infections</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Biologie</strong></span></td>\n            <td><span class=\"kw-bio\">protéinurie</span> <span class=\"kw-chiffre\">&gt; 3 g/24 h</span> (adulte) ou <span class=\"kw-chiffre\">&gt; 50 mg/kg/24 h</span> (enfant) ; <span class=\"kw-bio\">hypoalbuminémie &lt; 30 g/L</span> (pédiatrie : ± hypoprotidémie &lt;<span class=\"kw-chiffre\"> 60 g/L</span>) ; <span class=\"kw-bio\">complément (C3, C4, CH50) normal</span> (élimine GNA, <span class=\"kw-clinique\">lupus</span>, GNRP)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>PBR</strong></span></td>\n            <td><span class=\"kw-alerte\">non réalisée</span> si tous <span class=\"kw-clinique\">les</span> critères réunis : âge <span class=\"kw-chiffre\">1-10 ans</span> (<span class=\"kw-chiffre\">11 ans</span> selon pédiatrie), pas d'ATCD familial de néphropathie, SN <span class=\"kw-clinique\">pur</span>, pas de signe extra-rénal, <span class=\"kw-bio\">complément normal</span>, SN <span class=\"kw-clinique\">corticosensible</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>HSF = signal de sévérité.</strong> La présence de lésions d'<span class=\"kw-alerte\">HSF</span> au cours d'un SN idiopathique traduit une maladie <span class=\"kw-alerte\">plus sévère</span> (risque d'IRT en <span class=\"kw-chiffre\">5-20 ans</span>, récidive sur le greffon <span class=\"kw-chiffre\">30-35 %</span>) et une <span class=\"kw-alerte\">moins bonne réponse aux corticoïdes</span>.</div>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Enfant 1-10/<span class=\"kw-chiffre\">11 ans</span> + <span class=\"kw-clinique\">SN pur</span> + <span class=\"kw-bio\">complément</span> normal = <span class=\"kw-alerte\">SNLGM présumé → corticothérapie d'emblée sans PBR</span>. En cas de forme précoce ou cortico-résistante : rechercher une <span class=\"kw-clinique\">mutation des gènes podocytaires</span> (néphrine, podocine).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-clinique\">Syndrome néphrotique</span> · 51 — <span class=\"kw-clinique\">Œdèmes</span> / SN de l'enfant</em></p>","frequence":0},{"id":"261-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du SNLGM","contenu":"<p>Le traitement associe un <strong>traitement symptomatique</strong> du <span class=\"kw-clinique\">syndrome néphrotique</span> et un <strong>traitement spécifique</strong> (<span class=\"kw-ttt\">corticothérapie</span>), distinct.</p>\n      <p><strong>Traitement symptomatique du SN</strong></p>\n      <ul>\n        <li>Contrôle de la PA et de la <span class=\"kw-bio\">protéinurie</span> : <span class=\"kw-ttt\">restriction sodée &lt; 6 g/j</span>, <span class=\"kw-ttt\">IEC/ARA2</span></li>\n        <li>Prévention des thromboses : mobilisation, maintien de l'euvolémie, ± <span class=\"kw-ttt\">HBPM</span> et/ou <span class=\"kw-ttt\">aspirine</span></li>\n        <li><span class=\"kw-ttt\">Vaccination</span> <span class=\"kw-ttt\">pneumococcique 23-valente</span> + <span class=\"kw-ttt\">antigrippale annuelle</span> (vaccins vivants CI sous <span class=\"kw-ttt\">corticothérapie</span> forte dose / <span class=\"kw-ttt\">immunosuppresseur</span>)</li>\n        <li>Selon la situation : restriction hydrique si hyponatrémie ; perfusion d'<span class=\"kw-ttt\">albumine</span> si complication (hypovolémie, épanchements symptomatiques) ; <span class=\"kw-ci\">diurétiques à éviter</span> (risque de majorer hypovolémie et hypercoagulabilité)</li>\n      </ul>\n      <p><strong><span class=\"kw-ttt\">Corticothérapie</span></strong> (traitement spécifique)</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\"><strong>Attaque</strong></span></td><td><span class=\"kw-ttt\">prednisone</span> forte dose : <span class=\"kw-chiffre\">4 semaines</span> chez l'enfant ; jusqu'à la <span class=\"kw-clinique\">rémission</span> (<span class=\"kw-chiffre\">4-8 semaines</span>) chez l'adulte</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Décroissance</strong></span></td><td>diminution progressive, durée totale <span class=\"kw-chiffre\">4-5 mois</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Traitements adjuvants de la <span class=\"kw-ttt\">corticothérapie</span></strong></p>\n      <ul>\n        <li>Régime pauvre en sel, sucres rapides, calories</li>\n        <li>Supplémentation <span class=\"kw-ttt\">calcium + vitamine D</span> ; supplémentation potassique (selon <span class=\"kw-bio\">kaliémie</span>, non systématique)</li>\n        <li>Protection gastrique (non systématique selon pédiatrie) ; prévention des infections (pneumocystose, anguillulose) + mise à jour vaccinale</li>\n      </ul>\n      <p><strong><span class=\"kw-ttt\">Immunosuppresseurs</span> / immunomodulateurs</strong> — <span class=\"kw-ttt\">ciclosporine, mycophénolate mofétil, rituximab</span> : indiqués en cas de <span class=\"kw-clinique\">corticodépendance</span> ou <span class=\"kw-clinique\">corticorésistance</span>.</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> PEC <span class=\"kw-clinique\">100 % (ALD 30)</span> et PAI chez l'enfant. <span class=\"kw-def\">Suivi</span> : <span class=\"kw-clinique\">BU quotidienne</span> (carnet) pour dépister <span class=\"kw-clinique\">les</span> rechutes ; <span class=\"kw-def\">surveillance</span> des complications aiguës et des complications cortico-induites (retard de croissance surtout, surpoids, <span class=\"kw-etio\">HTA</span>, cataracte, ostéopénie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — Traitement symptomatique du SN · 330 — <span class=\"kw-ttt\">Corticoïdes</span></em></p>","frequence":0},{"id":"261-10","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principaux modes évolutifs du SNLGM","contenu":"<p>L'<span class=\"kw-clinique\">évolution</span> du SNLGM se décrit par la <strong>réponse à la <span class=\"kw-ttt\">corticothérapie</span></strong>, déterminante pour le <span class=\"kw-def\">pronostic</span>.</p>\n      <table >\n        <thead><tr><th>Profil évolutif</th><th>Définition · conséquence</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Corticosensibilité</strong></span> <span class=\"kw-chiffre\">(80-90 %)</span></td>\n            <td>réponse aux stéroïdes ; mais dans <span class=\"kw-alerte\">50 % des cas, rechute</span> ⚠️ nécessitant une reprise de la <span class=\"kw-ttt\">corticothérapie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Corticodépendance</strong></span></td>\n            <td>rechute lors de la <span class=\"kw-clinique\">diminution</span> de la <span class=\"kw-ttt\">corticothérapie</span>, ou dans <span class=\"kw-clinique\">les</span> mois suivant son <span class=\"kw-clinique\">arrêt</span> (<span class=\"kw-chiffre\">3 mois</span> enfant, <span class=\"kw-chiffre\">2 mois</span> adulte) → justifie souvent l'adjonction d'un <span class=\"kw-ttt\">immunosuppresseur</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Corticorésistance</strong></span> <span class=\"kw-chiffre\">(10 %)</span></td>\n            <td>non-réponse à dose maximale (après <span class=\"kw-chiffre\">4 sem.</span> enfant, <span class=\"kw-chiffre\">8 sem.</span> adulte) ; plus fréquente chez l'adulte (<span class=\"kw-chiffre\">20 %</span>) ; chez l'enfant impose une <span class=\"kw-imagerie\">PBR</span> ; nécessite un <span class=\"kw-ttt\">immunosuppresseur</span> ; <span class=\"kw-clinique\">évolution</span> vers une <span class=\"kw-alerte\">IRT dans 50 %</span> (avec récidive sur le greffon)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le SNLGM est très majoritairement <span class=\"kw-clinique\">corticosensible</span> (bon <span class=\"kw-def\">pronostic</span>) mais <span class=\"kw-alerte\">rechute une fois sur deux</span>. La <span class=\"kw-alerte\">corticorésistance</span> (souvent HSF sous-jacente) est de mauvais <span class=\"kw-def\">pronostic</span> et fait courir le risque d'<span class=\"kw-alerte\">IRT</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique / IRT · 197 — Transplantation rénale</em></p>","frequence":0},{"id":"261-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques et biologiques conduisant suspecter une glomérulopathie extra-membraneuse (GEM)","contenu":"<p>La GEM est la <strong>2ᵉ cause de <span class=\"kw-clinique\">syndrome néphrotique</span> de l'adulte</strong> (après le <span class=\"kw-etio\">diabète</span>) et la cause la plus fréquente de SN <span class=\"kw-clinique\">primitif</span> de l'adulte.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Terrain</strong></span></td><td>adulte, plus fréquent <span class=\"kw-chiffre\">&gt; 60 ans</span> ; rare chez l'enfant (&lt;<span class=\"kw-chiffre\"> 5 %</span>) ; prédominance masculine</td></tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Tableau clinique</strong></span></td>\n            <td><span class=\"kw-alerte\">syndrome néphrotique</span> (<span class=\"kw-chiffre\">85 %</span>), le plus souvent <span class=\"kw-clinique\">impur</span> (<span class=\"kw-bio\">hématurie</span> micro <span class=\"kw-chiffre\">40 %</span>, <span class=\"kw-etio\">HTA</span>, IRC <span class=\"kw-chiffre\">30 %</span>) ; complications du SN, dont la <span class=\"kw-alerte\">thrombose des veines rénales</span> particulièrement fréquente</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Anticorps anti-PLA2R</strong></span></td>\n            <td>recherche <strong>systématique</strong> ; s'il est positif, évoque la GEM primitive <strong>avant même la PBR</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic positif</span></strong></td>\n            <td>soit par <span class=\"kw-imagerie\">PBR</span> ; soit sans PBR devant l'association <span class=\"kw-clinique\">SN + anti-PLA2R sérique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Étiologies</strong></p>\n      <table >\n        <thead><tr><th>Forme</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>GEM primitive</strong></span> <span class=\"kw-chiffre\">(85 %)</span></td><td>dépôts extra-membraneux d'<span class=\"kw-chiffre\">IgG</span> ciblant un <span class=\"kw-bio\">antigène podocytaire = récepteur PLA2-R</span> <span class=\"kw-def\">(mémo : « j'aime les plats de Rachid » → PLA2R)</span></td></tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>GEM secondaire</strong></span> <span class=\"kw-chiffre\">(15 %)</span></td>\n            <td>mémo <strong>CLITO</strong> : <strong>C</strong>ancer (&gt;<span class=\"kw-chiffre\"> 50 ans</span> : pulmonaire, mammaire, colique, <span class=\"kw-clinique\">mélanome</span>) · <strong>L</strong>upus (femme <span class=\"kw-chiffre\">20-55 ans</span>, GN lupique classe 5) · <strong>I</strong>nfections (<span class=\"kw-etio\">VHB, VHC</span>, <span class=\"kw-clinique\">syphilis</span>, lèpre, filariose) · <strong>T</strong>oxiques/médicaments (<span class=\"kw-etio\">AINS</span>, D-pénicillamine) · <span class=\"kw-etio\">auto-immun</span> (<strong>O</strong> : <span class=\"kw-clinique\">Sjögren</span>, thyroïdite, sarcoïdose)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> <span class=\"kw-bio\">Anti-PLA2R positif</span> = GEM <strong>primitive</strong>. S'il est négatif, penser <strong>GEM secondaire</strong> et lancer l'enquête <strong>CLITO</strong> (notamment un <span class=\"kw-alerte\">cancer</span> après <span class=\"kw-chiffre\">50 ans</span>). <span class=\"kw-bio\">Histologie</span> : dépôts extra-membraneux granuleux <span class=\"kw-bio\">IgG + C3</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-clinique\">Syndrome néphrotique</span> · 194 — <span class=\"kw-clinique\">Lupus</span> · 167 — Hépatites · 290 — Cancers (<span class=\"kw-etio\">paranéoplasique</span>)</em></p>","frequence":2},{"id":"261-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques et biologiques conduisant suspecter une néphropathie à IgA","contenu":"<p>Objectif <span class=\"kw-alerte\">à fort rendement EDN</span> ⭐⭐⭐⭐. La néphropathie à <span class=\"kw-chiffre\">IgA</span> (maladie de Berger) est la <strong>glomérulopathie primitive la plus fréquente au monde</strong> ; sa présentation est <span class=\"kw-clinique\">dominée par l'hématurie</span>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Terrain</strong></span></td><td>adulte <span class=\"kw-clinique\">jeune</span> essentiellement, prédominance masculine</td></tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Présentations possibles</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">hématurie</span> <span class=\"kw-clinique\">isolée et asymptomatique</span> (découverte systématique)</li>\n                <li><span class=\"kw-alerte\">syndrome d'hématurie macroscopique récidivante</span> : totale, indolore, sans caillot, survenant typiquement dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48 h d'un épisode infectieux ORL</span></li>\n                <li><span class=\"kw-clinique\">syndrome de glomérulonéphrite</span> chronique (<span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-etio\">HTA</span>, IRC)</li>\n                <li><span class=\"kw-clinique\">syndrome néphrotique</span> <span class=\"kw-clinique\">impur</span></li>\n                <li>syndrome de <span class=\"kw-alerte\">GNRP (type 2)</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><span class=\"kw-bio\"><strong>Biologie</strong></span></td><td><span class=\"kw-bio\">complément sérique normal</span> ;<span class=\"kw-chiffre\"> 50 %</span> ont une ↑ des <span class=\"kw-chiffre\">IgA</span> sériques (IgA hypoglycosylées)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Diagnostic positif</span></strong></td><td>repose sur la <span class=\"kw-imagerie\">PBR</span> ; IF <strong>indispensable</strong> : dépôts <span class=\"kw-bio\">mésangiaux d'IgA et de C3</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Étiologies</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Maladie de Berger</span> = néphropathie à <span class=\"kw-chiffre\">IgA</span> <strong>primitive</strong> (rein exclusivement, pas d'atteinte extra-rénale) <span class=\"kw-def\">(≠ Buerger)</span></li>\n        <li><strong>Secondaires :</strong> cirrhose · <span class=\"kw-clinique\">MICI</span> · SpA · dermatose bulleuse · <span class=\"kw-etio\">purpura rhumatoïde</span> (garçon <span class=\"kw-chiffre\">≤ 8 ans</span>)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Néphropathie à <span class=\"kw-chiffre\">IgA</span> du <span class=\"kw-clinique\">purpura</span> rhumatoïde.</strong> Atteinte rénale inconstante mais à rechercher <span class=\"kw-alerte\">systématiquement</span> par <span class=\"kw-bio\">BU</span>. <span class=\"kw-imagerie\">Biopsie rénale</span> si : <span class=\"kw-etio\">HTA</span>, ou IR, ou <span class=\"kw-bio\">protéinurie</span> &gt;<span class=\"kw-chiffre\"> 1 g</span>/<span class=\"kw-chiffre\">24 h</span>, ou <span class=\"kw-bio\">protéinurie</span> durant &gt;<span class=\"kw-chiffre\"> 6 mois</span>. Formes sévères (rénales + digestives) : <span class=\"kw-ttt\">corticothérapie forte dose</span>.</div>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> <span class=\"kw-bio\">Hématurie</span> macroscopique <span class=\"kw-alerte\">contemporaine</span> (<span class=\"kw-chiffre\">48 h</span>) d'une infection ORL + <span class=\"kw-bio\">complément</span> <span class=\"kw-bio\">normal</span> + <span class=\"kw-bio\">IgA mésangiales</span> = néphropathie à <span class=\"kw-chiffre\">IgA</span>. À distinguer de la GNAPI (intervalle libre, hypocomplémentémie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-bio\">Hématurie</span> · 193 — <span class=\"kw-clinique\">Purpura</span> rhumatoïde / vascularites · 279 — Cirrhose</em></p>","frequence":4},{"id":"261-13","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principaux facteurs pronostiques de la néphropathie à IgA","contenu":"<p>Le <span class=\"kw-def\">pronostic</span> de la néphropathie à <span class=\"kw-chiffre\">IgA</span> est <strong>très variable</strong> : progression souvent lente, mais <span class=\"kw-alerte\">20-30 % des patients développent une IRT dans les 20 ans</span> suivant le diagnostic.</p>\n      <table >\n        <thead><tr><th>Facteurs cliniques</th><th>Facteurs histologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li>sexe <span class=\"kw-clinique\">masculin</span></li>\n                <li><span class=\"kw-def\">stade</span> de l'<span class=\"kw-clinique\">insuffisance rénale</span> au diagnostic</li>\n                <li>sévérité de l'<span class=\"kw-clinique\">HTA</span></li>\n                <li>importance de la <span class=\"kw-bio\">protéinurie</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>sévérité de la <span class=\"kw-clinique\">prolifération glomérulaire</span> (mésangiale, endocapillaire, extracapillaire)</li>\n                <li><span class=\"kw-clinique\">sclérose glomérulaire</span></li>\n                <li><span class=\"kw-clinique\">fibrose interstitielle</span></li>\n                <li><span class=\"kw-alerte\">lésions vasculaires</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le facteur pronostique clinique le plus opérant est l'importance de la <span class=\"kw-bio\">protéinurie</span> (cible thérapeutique néphroprotectrice). Côté <span class=\"kw-bio\">histologie</span>, la <span class=\"kw-clinique\">fibrose interstitielle</span> et <span class=\"kw-clinique\">les</span> lésions chroniques sont déterminantes. La <span class=\"kw-clinique\">récidive histologique sur le greffon</span> est fréquente (rarement responsable de la perte du greffon).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — IRC · 197 — Transplantation rénale</em></p>","frequence":1},{"id":"261-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques et biologiques conduisant suspecter d’une glomérulonéphrite rapidement progressive (GNRP)","contenu":"<p>Objectif <span class=\"kw-alerte\">à très fort rendement EDN</span> ⭐⭐⭐⭐⭐⭐⭐. La GNRP est une <strong><span class=\"kw-alerte\">urgence</span> néphrologique</strong> : la <span class=\"kw-alerte\">biopsie rénale doit être réalisée en urgence 🔥</span>.</p>\n      <div class=\"callout callout-danger\">\n        <p style=\"margin:0 0 6px\"><strong>Définition — syndrome clinique de GNRP</strong> (à ne pas confondre avec la « GN nécrosante à croissants », entité anatomopathologique) :</p>\n        <ul style=\"margin:0\">\n          <li><span class=\"kw-bio\">protéinurie</span> de débit glomérulaire (<span class=\"kw-chiffre\">&gt; 1 g/g de créatininurie</span>)</li>\n          <li><span class=\"kw-bio\">hématurie</span> abondante (parfois macroscopique)</li>\n          <li><span class=\"kw-alerte\">insuffisance rénale rapidement progressive</span> (<span class=\"kw-chiffre\">jours – semaines</span>)</li>\n        </ul>\n      </div>\n      <p><strong><span class=\"kw-def\">Classification</span> en 3 types (selon l'<span class=\"kw-bio\">immunofluorescence</span>)</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Dépôts · étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Type 1</strong></span></td>\n            <td>dépôts <span class=\"kw-clinique\">linéaires</span> intra-membraneux d'<span class=\"kw-chiffre\">IgG</span> anti-MBG → <span class=\"kw-etio\">maladie de Goodpasture</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Type 2</strong></span></td>\n            <td>dépôts <span class=\"kw-clinique\">granuleux</span> de complexes immuns endomembraneux → <span class=\"kw-etio\">LED</span> (hypocomplémentémie : <span class=\"kw-chiffre\">IgG</span>/IgA/IgM/<span class=\"kw-bio\">C3</span>/C1q) · <span class=\"kw-etio\">cryoglobulinémie</span> (IgG/IgM/C3) · <span class=\"kw-etio\">infections / GNAPI</span> (C3) · <span class=\"kw-etio\">purpura rhumatoïde, IgA primitive</span> (<span class=\"kw-chiffre\">IgA</span>/C3, pas d'hypocomplémentémie)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Type 3</strong></span></td>\n            <td>GN « <span class=\"kw-clinique\">pauci-immune</span> » (absence de dépôts) → <span class=\"kw-etio\">GPA</span> (cANCA <span class=\"kw-bio\">anti-PR3</span> circulants) · <span class=\"kw-etio\">MPA</span> (pANCA <span class=\"kw-bio\">anti-MPO</span> circulants)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <p style=\"margin:0 0 6px\"><strong>Maladie de Goodpasture (GNRP type 1)</strong> — AC anti-MBG dirigés contre le <span class=\"kw-bio\">collagène de type 4</span> (<span class=\"kw-bio\">antigène</span> commun aux membranes basales <span class=\"kw-clinique\">glomérulaire et alvéolaire</span>) :</p>\n        <ul style=\"margin:0\">\n          <li><span class=\"kw-alerte\">Syndrome pneumo-rénal</span> = GNRP + <span class=\"kw-alerte\">hémorragie intra-alvéolaire</span> (atteintes parfois dissociées)</li>\n          <li>Pulmonaire (souvent révélateur) : <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">dyspnée</span>, hémoptysie, <span class=\"kw-alerte\">détresse</span> respiratoire ; <span class=\"kw-imagerie\">RXT</span> <span class=\"kw-radio\">infiltrats bilatéraux</span> ; LBA hémorragie alvéolaire (sidérophages)</li>\n          <li>Biologie : <span class=\"kw-bio\">AC anti-MBG circulants +++</span> ; anémie microcytaire (carence martiale liée aux hémorragies)</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant une <span class=\"kw-alerte\">IRA + hématurie + protéinurie</span> d'installation rapide → évoquer une GNRP et <span class=\"kw-alerte\">biopsier en urgence</span>. Le trio diagnostique : <span class=\"kw-bio\">anti-MBG</span> (T1), <span class=\"kw-bio\">complément</span> + complexes immuns (T2), <span class=\"kw-bio\">ANCA</span> (T3). Tout syndrome pneumo-rénal n'est pas un Goodpasture (<span class=\"kw-clinique\">GPA</span>, MPA, cryo, <span class=\"kw-clinique\">purpura</span> rhumatoïde).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — Vascularites / <span class=\"kw-bio\">ANCA</span> · 194 — <span class=\"kw-clinique\">Lupus</span> · 359 — <span class=\"kw-alerte\">Détresse</span> respiratoire / hémorragie alvéolaire</em></p>","frequence":7},{"id":"261-15","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les facteurs de gravité d’un syndrome de GNRP","contenu":"<p>La GNRP est une <strong><span class=\"kw-alerte\">urgence</span> diagnostique et thérapeutique</strong> : tout retard compromet le <span class=\"kw-def\">pronostic</span> rénal. <span class=\"kw-clinique\">Les</span> facteurs de gravité sont rénaux, extra-rénaux et histologiques.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Facteurs de gravité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Rénal</strong></span></td>\n            <td><span class=\"kw-ci\">insuffisance rénale</span> rapidement progressive, souvent <span class=\"kw-clinique\">oligo-anurique</span> ; importance de la <span class=\"kw-bio\">protéinurie</span> ; <span class=\"kw-def\">stade</span> de l'IR au diagnostic</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Pulmonaire</strong></span> (Goodpasture, vascularites)</td>\n            <td><span class=\"kw-alerte\">hémorragie intra-alvéolaire</span> → <span class=\"kw-def\">pronostic</span> <span class=\"kw-alerte\">vital</span> en jeu (<span class=\"kw-alerte\">détresse</span> respiratoire, <span class=\"kw-clinique\">hémoptysie</span>) ; risque de rechutes</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Histologique</strong></span></td>\n            <td>proportion de <span class=\"kw-alerte\">croissants</span> (prolifération extracapillaire) ; étendue des <span class=\"kw-alerte\">cicatrices fibreuses</span> — plus <span class=\"kw-clinique\">les</span> lésions chroniques sont importantes, plus le <span class=\"kw-def\">pronostic</span> rénal est altéré</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Réflexe <span class=\"kw-alerte\">urgence</span>.</strong> Devant une suspicion de GNRP : <span class=\"kw-imagerie\">PBR en urgence</span>, recherche d'une <span class=\"kw-alerte\">hémorragie alvéolaire</span> (syndrome pneumo-rénal mettant en jeu le <span class=\"kw-alerte\">pronostic vital</span>), et mise en route rapide du traitement spécifique (<span class=\"kw-ttt\">corticoïdes</span>, ± échanges plasmatiques). Le <span class=\"kw-def\">pronostic</span> rénal dépend de la <strong>précocité</strong> de la prise en charge.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë · 193 — Vascularites</em></p>","frequence":0},{"id":"261-16","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques et biologiques conduisant suspecter une glomérulonéphrite aiguë post infectieuse (GNA)","contenu":"<p>La GNA post-infectieuse réalise le tableau typique de <strong><span class=\"kw-clinique\">syndrome néphritique</span> aigu</strong>. Forme classique = GNA <span class=\"kw-clinique\">post-streptococcique</span> (ou staphylococcique).</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Contexte</strong></span></td>\n            <td>survient après un <span class=\"kw-alerte\">intervalle libre de ≈ 15 jours</span> succédant à un épisode <span class=\"kw-etio\">infectieux</span> <span class=\"kw-clinique\">ORL ou cutané</span> non traité par antibiotiques</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Syndrome néphritique aigu</strong></span></td>\n            <td>\n              <ul>\n                <li>début <span class=\"kw-clinique\">brutal</span>, installation en quelques jours</li>\n                <li>surcharge hydrosodée : <span class=\"kw-clinique\">œdèmes</span>, voire <span class=\"kw-alerte\">OAP</span></li>\n                <li><span class=\"kw-bio\">protéinurie</span> glomérulaire</li>\n                <li><span class=\"kw-bio\">hématurie</span> (parfois macroscopique)</li>\n                <li><span class=\"kw-clinique\">HTA</span></li>\n                <li><span class=\"kw-clinique\">insuffisance rénale aiguë</span> (organique)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Enfant ou adulte présentant <span class=\"kw-clinique\">œdèmes</span> + <span class=\"kw-etio\">HTA</span> + <span class=\"kw-bio\">hématurie</span> + IRA <strong>~<span class=\"kw-chiffre\">15 jours</span> après</strong> une angine ou une infection cutanée non traitée → <span class=\"kw-etio\">GNA post-infectieuse</span>. L'<span class=\"kw-bio\">hypocomplémentémie transitoire</span> est l'élément paraclinique clé (cf. objectif suivant).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-bio\">Hématurie</span> · 155 — Infections ORL · 152 — Infections cutanées</em></p>","frequence":0},{"id":"261-17","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les éléments paracliniques conduisant suspecter une glomérulonéphrite aiguë post infectieuse (GNA)","contenu":"<p>Le diagnostic de GNA post-infectieuse est avant tout <strong>clinique et <span class=\"kw-ttt\">biologique</span></strong> ; la PBR n'est réalisée qu'en cas de doute.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Résultat</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Complément</strong></span></td>\n            <td><span class=\"kw-alerte\">hypocomplémentémie fréquente</span> : baisse du <span class=\"kw-bio\">C3, C4</span>, puis <span class=\"kw-clinique\">normalisation dans les 2 mois</span> (caractère transitoire +++)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>PBR</strong></span></td>\n            <td>réalisée seulement <span class=\"kw-clinique\">en cas de doute diagnostique</span> (<span class=\"kw-def\">diagnostic différentiel</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>MO</strong></span></td>\n            <td>prolifération <span class=\"kw-clinique\">endocapillaire diffuse</span> (afflux de PNN ++) ; volumineux dépôts extra-membraneux irréguliers (« <span class=\"kw-clinique\">humps</span> ») ; prolifération extracapillaire dans <span class=\"kw-clinique\">les</span> formes sévères</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>IF</strong></span></td>\n            <td>dépôts <span class=\"kw-clinique\">mésangiaux et extra-membraneux</span>, aspect en « <span class=\"kw-clinique\">ciel étoilé</span> », nature : <span class=\"kw-bio\">C3</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Triade paraclinique : <span class=\"kw-bio\">hypocomplémentémie transitoire (C3/C4, normalisée en 2 mois)</span>, « <span class=\"kw-clinique\">humps</span> » en MO, <span class=\"kw-bio\">C3 en « ciel étoilé »</span> en IF. L'hypocomplémentémie <strong>transitoire</strong> distingue la GNA d'une cause persistante (<span class=\"kw-clinique\">lupus</span>, cryoglobulinémie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-bio\">Hématurie</span> · 194 — <span class=\"kw-clinique\">Lupus</span> (hypocomplémentémie persistante)</em></p>","frequence":1},{"id":"261-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des principales glomérulopathies (autres que SNLGM)","contenu":"<p>Toutes <span class=\"kw-clinique\">les</span> glomérulopathies relèvent d'un <strong>traitement néphroprotecteur symptomatique</strong> commun ; certaines ont un <strong>traitement spécifique</strong>. Socle néphroprotecteur : <span class=\"kw-ttt\">restriction sodée &lt; 6 g/j</span>, <span class=\"kw-ttt\">IEC/ARA2</span> (contrôle PA + <span class=\"kw-bio\">protéinurie</span>), ± <span class=\"kw-ttt\">diurétique</span>.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Traitement spécifique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>GEM</strong></span></td>\n            <td>traitement symptomatique du SN ; GEM secondaire → traiter/éradiquer la cause ; GEM primitive → <span class=\"kw-ttt\">rituximab</span> discuté si <span class=\"kw-alerte\">SN persistant à 6 mois</span> et/ou <span class=\"kw-clinique\">insuffisance rénale</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Néphropathie à IgA</strong></span></td>\n            <td>aucun traitement codifié : traitement <span class=\"kw-ttt\">symptomatique et néphroprotecteur</span> ; <span class=\"kw-ttt\">corticoïdes</span> discutés en milieu spécialisé, voire <span class=\"kw-ttt\">immunosuppresseurs</span> dans <span class=\"kw-clinique\">les</span> formes graves</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>GNRP type 3 (pauci-immune, ANCA)</strong></span></td>\n            <td><strong>Phase aiguë :</strong> <span class=\"kw-ttt\">corticothérapie</span> + <span class=\"kw-ttt\">cyclophosphamide IV ou rituximab</span> ; <span class=\"kw-ttt\">échanges plasmatiques</span> dans <span class=\"kw-clinique\">les</span> formes rénales sévères<br><strong>Entretien (<span class=\"kw-chiffre\">≥ 2 ans</span>) :</strong> <span class=\"kw-ttt\">azathioprine</span> ou <span class=\"kw-ttt\">rituximab</span> (fréquence des rechutes)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Goodpasture (GNRP type 1)</strong></span></td>\n            <td>symptomatique (déplétion hydrosodée, O₂, PEC de l'IRA et de l'anémie) + <span class=\"kw-ttt\">corticoïdes fortes doses IV</span> + <span class=\"kw-ttt\">échanges plasmatiques ++</span> + <span class=\"kw-ttt\">cyclophosphamide</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>GNA post-infectieuse</strong></span></td>\n            <td>traitement <span class=\"kw-alerte\">exclusivement symptomatique</span> ; <span class=\"kw-def\">pronostic</span> excellent (guérison en <span class=\"kw-chiffre\">2 mois</span> chez <span class=\"kw-chiffre\">90 %</span> des enfants,<span class=\"kw-chiffre\"> 80 %</span> des adultes)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <p style=\"margin:0 0 6px\"><strong>Mesures associées sous <span class=\"kw-ttt\">immunosuppresseurs</span> / <span class=\"kw-ttt\">corticothérapie</span></strong></p>\n        <ul style=\"margin:0\">\n          <li>éradication des foyers <span class=\"kw-etio\">infectieux</span> (ORL, dentaires), prévention des infections opportunistes (<span class=\"kw-ttt\">cotrimoxazole</span>)</li>\n          <li>adjuvants : régime pauvre en sel/sucres rapides/calories, <span class=\"kw-ttt\">calcium + vitamine D</span>, ± potassium, protection gastrique</li>\n          <li><span class=\"kw-def\">surveillance</span> : <span class=\"kw-bio\">NFS</span> (leucopénie sous <span class=\"kw-ttt\">cyclophosphamide</span>), <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">protéinurie</span>/<span class=\"kw-bio\">hématurie</span>, quantification des <span class=\"kw-bio\">ANCA</span></li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Deux réflexes : <span class=\"kw-ttt\">échanges plasmatiques</span> dans le Goodpasture et <span class=\"kw-clinique\">les</span> formes rénales sévères de vascularites <span class=\"kw-bio\">ANCA</span> ; <span class=\"kw-ttt\">rituximab</span> dans la GEM primitive résistante (&gt;<span class=\"kw-chiffre\"> 6 mois</span>) et l'entretien des vascularites. La <span class=\"kw-etio\">GNA post-infectieuse</span> = symptomatique seul.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — Vascularites · 330 — <span class=\"kw-ttt\">Corticoïdes</span> / <span class=\"kw-ttt\">immunosuppresseurs</span> · 264 — Néphroprotection</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>GNRP <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> néphrologique</span></strong></p><p><span class=\"kw-imagerie\">PBR en urgence 🔥</span> + mise en route rapide du traitement spécifique — le <span class=\"kw-def\">pronostic</span> rénal dépend de la <span class=\"kw-alerte\">précocité</span> de la PEC</p><ul><li><span class=\"kw-alerte\">Insuffisance rénale rapidement progressive</span> (<span class=\"kw-chiffre\">jours – semaines</span>) + <span class=\"kw-clinique\">hématurie</span> abondante + <span class=\"kw-bio\">protéinurie</span> glomérulaire</li><li>Rechercher d'emblée une <span class=\"kw-alerte\">hémorragie intra-alvéolaire</span> (syndrome pneumo-rénal)</li></ul><p><strong>Syndrome pneumo-rénal <span class=\"q\">— maladie de Goodpasture</span></strong></p><p><span class=\"kw-ttt\">corticoïdes fortes doses IV</span> + <span class=\"kw-ttt\">échanges plasmatiques ++</span> + <span class=\"kw-ttt\">cyclophosphamide</span> sans délai</p><ul><li><span class=\"kw-alerte\">Hémorragie intra-alvéolaire</span> → <span class=\"kw-alerte\">pronostic vital</span> engagé (<span class=\"kw-alerte\">détresse</span> respiratoire, <span class=\"kw-clinique\">hémoptysie</span>)</li></ul><p><strong><span class=\"kw-clinique\">Syndrome néphritique</span> aigu <span class=\"q\">— GNA post-infectieuse</span></strong></p><p>traitement <span class=\"kw-alerte\">symptomatique</span> de la surcharge (déplétion hydrosodée)</p><ul><li>Début <span class=\"kw-clinique\">brutal</span> (quelques jours) : surcharge hydrosodée pouvant aller jusqu'à l'<span class=\"kw-alerte\">OAP</span></li></ul>","hospit":"<p><strong>PBR :</strong> <span class=\"kw-clinique\">hospitalisation indispensable</span> — bilan d'hémostase (<span class=\"kw-bio\">NFS, TP, TCA</span>), <span class=\"kw-bio\">groupe sanguin + RAI</span>, <span class=\"kw-imagerie\">imagerie rénale récente</span> ; indication posée ou confirmée par un <strong>néphrologue</strong>.<br><strong>GNRP :</strong> <span class=\"kw-alerte\">urgence néphrologique</span> → orientation immédiate pour <span class=\"kw-imagerie\">PBR en urgence</span> et traitement spécifique.<br><strong>SNLGM de l'enfant :</strong> prise en charge à <span class=\"kw-clinique\">100 % (ALD 30)</span> et PAI.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Insuffisance rénale rapidement progressive</span>, souvent <span class=\"kw-clinique\">oligo-anurique</span> → GNRP</li><li><span class=\"kw-alerte\">Hémorragie intra-alvéolaire</span> (syndrome pneumo-rénal) → <span class=\"kw-alerte\">pronostic vital</span> engagé</li><li>Surcharge hydrosodée avec <span class=\"kw-alerte\">OAP</span> (<span class=\"kw-clinique\">syndrome néphritique</span> aigu)</li><li>Forte proportion de <span class=\"kw-alerte\">croissants</span> et de <span class=\"kw-alerte\">cicatrices fibreuses</span> sur la PBR → <span class=\"kw-def\">pronostic</span> rénal altéré</li><li>Lésions d'<span class=\"kw-alerte\">HSF</span> au cours d'un SN idiopathique = maladie plus sévère (risque d'<span class=\"kw-alerte\">IRT</span>, moins bonne réponse aux <span class=\"kw-ttt\">corticoïdes</span>)</li><li><span class=\"kw-alerte\">Corticorésistance</span> du SNLGM → <span class=\"kw-clinique\">évolution</span> vers l'<span class=\"kw-alerte\">IRT</span> dans <span class=\"kw-chiffre\">50 %</span> des cas</li><li><span class=\"kw-alerte\">Thrombose des veines rénales</span> — complication particulièrement fréquente de la GEM</li></ul>","principes":"<p>Socle néphroprotecteur commun à toute glomérulopathie : <span class=\"kw-ttt\">restriction sodée &lt; 6 g/j</span> + <span class=\"kw-ttt\">IEC/ARA2</span> (contrôle de la <span class=\"kw-clinique\">PA</span> et de la <span class=\"kw-bio\">protéinurie</span>), ± <span class=\"kw-ttt\">diurétique</span>. Certaines entités ont en plus un <strong>traitement spécifique</strong>.</p><p><strong>SNLGM</strong></p><ul><li>Symptomatique du SN + <span class=\"kw-ttt\">corticothérapie</span> (<span class=\"kw-ttt\">prednisone</span> forte dose, décroissance sur <span class=\"kw-chiffre\">4–5 mois</span>)</li><li><span class=\"kw-ttt\">Ciclosporine</span>, <span class=\"kw-ttt\">mycophénolate mofétil</span> ou <span class=\"kw-ttt\">rituximab</span> si <span class=\"kw-clinique\">corticodépendance</span> ou <span class=\"kw-clinique\">corticorésistance</span></li></ul><p><strong>GEM</strong></p><ul><li>Traitement <span class=\"kw-ttt\">symptomatique</span> du SN ; GEM secondaire → traiter / éradiquer la cause</li><li>GEM primitive : <span class=\"kw-ttt\">rituximab</span> discuté si <span class=\"kw-alerte\">SN persistant à 6 mois</span> et/ou <span class=\"kw-alerte\">insuffisance rénale</span></li></ul><p><strong>Néphropathie à <span class=\"kw-chiffre\">IgA</span></strong></p><ul><li>Aucun traitement codifié : <span class=\"kw-ttt\">symptomatique et néphroprotecteur</span></li><li><span class=\"kw-ttt\">Corticoïdes</span> discutés en milieu spécialisé, voire <span class=\"kw-ttt\">immunosuppresseurs</span> dans <span class=\"kw-clinique\">les</span> formes graves</li></ul><p><strong>GNRP type 3 <span class=\"q\">— pauci-immune (<span class=\"kw-bio\">ANCA</span>)</span></strong></p><ul><li>Phase aiguë : <span class=\"kw-ttt\">corticothérapie</span> + <span class=\"kw-ttt\">cyclophosphamide IV ou rituximab</span> ; <span class=\"kw-ttt\">échanges plasmatiques</span> si forme rénale sévère</li><li>Entretien <span class=\"kw-chiffre\">≥ 2 ans</span> : <span class=\"kw-ttt\">azathioprine</span> ou <span class=\"kw-ttt\">rituximab</span> (fréquence des rechutes)</li></ul><p><strong>Goodpasture <span class=\"q\">— GNRP type 1</span></strong></p><ul><li>Symptomatique (déplétion hydrosodée, <span class=\"kw-ttt\">O₂</span>, PEC de l'IRA et de l'anémie)</li><li><span class=\"kw-ttt\">Corticoïdes fortes doses IV</span> + <span class=\"kw-ttt\">échanges plasmatiques ++</span> + <span class=\"kw-ttt\">cyclophosphamide</span></li></ul><p><strong>GNA post-infectieuse</strong></p><ul><li>Traitement <span class=\"kw-alerte\">exclusivement symptomatique</span> ; <span class=\"kw-def\">pronostic</span> excellent (guérison en <span class=\"kw-chiffre\">2 mois</span>)</li></ul>","suivi":"<p><strong>SNLGM</strong></p><ul><li><span class=\"kw-clinique\">BU quotidienne</span> (carnet de <span class=\"kw-def\">suivi</span>) pour dépister <span class=\"kw-clinique\">les</span> rechutes</li><li>Surveiller <span class=\"kw-clinique\">les</span> complications aiguës et les complications <span class=\"kw-clinique\">cortico-induites</span> (retard de croissance, surpoids, <span class=\"kw-etio\">HTA</span>, cataracte, ostéopénie)</li></ul><p><strong>Sous <span class=\"kw-ttt\">immunosuppresseurs</span> / <span class=\"kw-ttt\">corticothérapie</span></strong></p><ul><li>Biologie : <span class=\"kw-bio\">NFS</span> (leucopénie sous <span class=\"kw-ttt\">cyclophosphamide</span>), <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">protéinurie / hématurie</span>, quantification des <span class=\"kw-bio\">ANCA</span></li><li>Éradication des foyers <span class=\"kw-etio\">infectieux</span> (ORL, dentaires) + prévention des infections opportunistes (<span class=\"kw-ttt\">cotrimoxazole</span>)</li></ul><p><strong>GNA post-infectieuse</strong></p><ul><li><span class=\"kw-bio\">Hypocomplémentémie transitoire</span> → normalisation du <span class=\"kw-bio\">C3 / C4</span> en <span class=\"kw-chiffre\">2 mois</span> (caractère transitoire +++)</li></ul><p><strong>Néphropathie à <span class=\"kw-chiffre\">IgA</span></strong></p><ul><li>Cible thérapeutique = <span class=\"kw-ttt\">réduction</span> de la <span class=\"kw-alerte\">protéinurie</span> (facteur pronostique majeur)</li><li><span class=\"kw-clinique\">Récidive histologique sur le greffon</span> fréquente (rarement responsable de la perte du greffon)</li></ul>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique13","label":"Collège CUEN — Néphropathies glomérulaires"}],"cards":[]};